const followUp = $('Loop Over Follow-ups').first().json;
const leadData = $input.first().json[0] || {};

const day = followUp.sequence_day;

// Email templates per day
const templates = {
  0: {
    subject: `Welcome to Synergistic AI, ${leadData.first_name || 'there'}! Here's what happens next`,
    intro: `Thank you for connecting with us! We're thrilled to learn about your business and explore how we can help you achieve your goals with AI and automation.`,
    body: `Our team has reviewed your inquiry about <b>${leadData.service_of_interest || 'our services'}</b> and we're ready to help.\n\n<b>Here's what to expect:</b>\n✅ A personalized strategy session with our AI experts\n✅ A custom automation roadmap for your business\n✅ Clear pricing and timeline estimates\n✅ No pressure, no obligation`,
    cta: 'Schedule Your Free Strategy Session',
    ctaUrl: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
  },
  1: {
    subject: `How ${leadData.service_of_interest || 'AI Automation'} works at Synergistic AI`,
    intro: `Yesterday you reached out about ${leadData.service_of_interest || 'our services'}. Today I want to give you a deeper look at exactly how we work.`,
    body: `<b>Our Proven Process:</b>\n\n<b>Step 1: Discovery (Week 1)</b>\nWe map your current workflows, identify automation opportunities, and define clear ROI targets.\n\n<b>Step 2: Build (Weeks 2-4)</b>\nOur team builds your custom automation system — no off-the-shelf solutions.\n\n<b>Step 3: Test & Launch (Week 5)</b>\nRigorous testing, staff training, and a smooth go-live.\n\n<b>Step 4: Optimise (Ongoing)</b>\nWe monitor performance, refine automations, and scale as your business grows.`,
    cta: 'See Our Full Process',
    ctaUrl: 'https://synergisticaisolns.com'
  },
  3: {
    subject: `How a similar business automated their ${leadData.service_of_interest || 'operations'} [Case Study]`,
    intro: `Real results speak louder than promises. Here's how a business similar to ${leadData.company || 'yours'} transformed their operations with our help.`,
    body: `<b>📊 Case Study: B2B Services Company</b>\n\n<b>Challenge:</b> Manual lead qualification taking 4+ hours/day. CRM data out of sync. Sales team overwhelmed.\n\n<b>Solution:</b> Custom AI chatbot + n8n automation + HubSpot CRM integration\n\n<b>Results (90 days):</b>\n🚀 <b>340% increase</b> in qualified leads captured\n⏱️ <b>18 hours/week saved</b> on manual data entry\n💰 <b>$127K additional pipeline</b> from leads that would have been missed\n📈 <b>28% improvement</b> in lead-to-meeting conversion rate\n\nThis is what's possible for ${leadData.company || 'your business'} too.`,
    cta: 'Get Results Like This',
    ctaUrl: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
  },
  5: {
    subject: `Your free strategy session is still available, ${leadData.first_name || 'there'}`,
    intro: `A quick friendly reminder — your complimentary 30-minute AI strategy session is still open and waiting for you.`,
    body: `In this session, we'll:\n\n✅ Review your specific business challenge: "${leadData.message?.slice(0, 100) || 'your automation goals'}"\n✅ Show you a live demo of what's possible for your business\n✅ Give you a concrete roadmap — even if you decide not to work with us\n✅ Answer every question you have about AI, automation, and ROI\n\n<b>Zero pressure. Zero obligation. 100% value.</b>\n\nSpots are limited — our team books up quickly.`,
    cta: 'Book My Free Session Now',
    ctaUrl: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
  },
  7: {
    subject: `🎁 Exclusive offer for you — this week only`,
    intro: `I don't want to let you slip away without giving you every reason to get started.`,
    body: `For the next 7 days, we're offering <b>new clients a free AI readiness audit</b> (normally $500) when they sign up for any of our services.\n\n<b>What's included in your free audit:</b>\n📋 Full mapping of your current business processes\n🤖 AI automation opportunity assessment\n💰 ROI projections for each identified opportunity\n🗺️ A prioritised implementation roadmap\n\nThis offer expires in 7 days and is limited to 5 new clients this month.\n\n<b>Based on what you shared with us, we believe we can save ${leadData.company || 'your business'} significant time and money — and we want to prove it to you.</b>`,
    cta: 'Claim My Free AI Audit',
    ctaUrl: process.env.CALENDLY_BOOKING_URL || 'https://calendly.com/synergistic-ai'
  }
};

const template = templates[day] || templates[1];

const emailHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f5f5f5;">
<div style="max-width:600px;margin:0 auto;background:#fff;">
  <div style="background:#1E3A5F;padding:24px 32px;">
    <h1 style="color:#fff;margin:0;font-size:24px;">Synergistic AI Solutions</h1>
    <p style="color:#00A8E8;margin:4px 0 0;">AI Automation & Digital Marketing</p>
  </div>
  <div style="padding:32px;">
    <p style="color:#333;font-size:16px;">Hi ${leadData.first_name || 'there'},</p>
    <p style="color:#333;font-size:15px;line-height:1.6;">${template.intro}</p>
    <div style="background:#f9f9f9;border-left:4px solid #00A8E8;padding:20px 24px;margin:24px 0;border-radius:0 8px 8px 0;">
      <p style="color:#333;font-size:15px;line-height:1.8;margin:0;">${template.body.replace(/\n/g, '<br>')}</p>
    </div>
    <div style="text-align:center;margin:32px 0;">
      <a href="${template.ctaUrl}" style="background:#1E3A5F;color:#fff;padding:16px 32px;text-decoration:none;border-radius:6px;font-weight:bold;font-size:16px;display:inline-block;">${template.cta} →</a>
    </div>
    <p style="color:#666;font-size:14px;">— Vijay Davala<br>Founder, Synergistic AI Solutions<br><a href="https://synergisticaisolns.com" style="color:#00A8E8;">synergisticaisolns.com</a></p>
  </div>
  <div style="background:#1E3A5F;padding:16px 32px;text-align:center;">
    <p style="color:#aaa;font-size:12px;margin:0;">© 2026 Synergistic AI Solutions | <a href="https://synergisticaisolns.com" style="color:#00A8E8;">synergisticaisolns.com</a><br>You received this because you contacted us. <a href="#unsubscribe" style="color:#aaa;">Unsubscribe</a></p>
  </div>
</div>
</body></html>`;

return [{
  json: {
    follow_up_id: followUp.id,
    lead_id: leadData.id,
    to_email: leadData.business_email,
    first_name: leadData.first_name,
    subject: template.subject,
    email_html: emailHtml,
    sequence_day: day
  }
}];

// Also called directly from WF5 to enroll a NEW lead in the sequence
// This sub-function creates the follow_up rows for days 0,1,3,5,7
const input = $input.first().json;
const leadId = input.lead_id;

const now = new Date();
const days = [0, 1, 3, 5, 7];

const rows = days.map(day => {
  const scheduledAt = new Date(now.getTime() + day * 24 * 60 * 60 * 1000);
  // For day 0 schedule 30 minutes from now
  if (day === 0) scheduledAt.setMinutes(scheduledAt.getMinutes() + 30);
  return {
    lead_id: leadId,
    sequence_day: day,
    scheduled_at: scheduledAt.toISOString(),
    status: 'pending'
  };
});

return [{ json: { rows, lead_id: leadId } }];
